/*
 * VM Program: heartbeat_combined (20 bytes)
 * Runs Frida detection + CRC32 check in one VM execution.
 * If Frida detected: R0=0xFFFFFFFF. Otherwise R0=CRC32 of .text.
 *
 * Registers:
 *   R0 = result (CRC32 or error marker)
 *   R1 = frida detection temp
 *
 * Encoding:
 *   00: HYPERCALL FRIDA(3), R1, 0, 0   // R1 = frida result
 *   06: CMP       R1, R0                // R0 defaults to 0
 *   08: JNE       frida_hit             // → 0x13
 *   0D: HYPERCALL CRC32(4), R0, 0, 0   // R0 = CRC32
 *   13: HALT
 */
extern const uint8_t g_vm_heartbeat_combined[] = {
    /* 00 */ 0x32, 0x03, 0x01, 0x00, 0x00, 0x00,  // HYPERCALL FRIDA, R1
    /* 06 */ 0x20, 0x10,                             // CMP R1, R0
    /* 08 */ 0x23, 0x00, 0x00, 0x00, 0x13,         // JNE 0x13
    /* 0D */ 0x32, 0x04, 0x00, 0x00, 0x00, 0x00,  // HYPERCALL CRC32, R0
    /* 13 */ 0xFF                                    // HALT
};
extern const uint32_t g_vm_heartbeat_combined_size = sizeof(g_vm_heartbeat_combined);

